Scaffold(snackbarHost = { MonarchSnackbarHost(hostState = snackbars) }) { padding ->
    MonarchButton(
        text = {{trigger}},
        onClick = {
            step = 0
            allTo = null
            perItem = false
            each.clear()
            open = true
        },
        modifier = Modifier.padding(padding),
        variant = MonarchButtonVariant.Danger,
    )
}
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }, title = {{title}}, dismissible = !removing) {
        val sheet = this
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            MonarchText(text = "Step ${step + 1} of 2", style = MonarchTextStyle.Caption)
            MonarchProgress(progress = (step + 1) / 2f, size = MonarchProgressSize.Sm)
            if (step == 0) {
                MonarchText(text = {{handOver.heading}}, style = MonarchTextStyle.Heading)
                MonarchText(text = {{handOver.description}})
                if (!perItem) {
                    MonarchAssigneePicker(
                        people = people,
                        selected = allTo,
                        onSelectedChange = { allTo = it },
                        currentUserId = {{currentUserId}},
                        showAssignToMe = false,
                        labels = MonarchAssigneePickerLabels(label = {{handOver.reassign}}, unassigned = {{handOver.unassigned}}),
                    )
                }
                MonarchCheckboxRow(
                    checked = perItem,
                    onCheckedChange = { on ->
                        if (on) work.forEach { each[it.id] = allTo }
                        perItem = on
                    },
                    label = {{handOver.perKind}},
                )
                if (perItem) {
                    work.forEach { w ->
                        MonarchAssigneePicker(
                            people = people,
                            selected = each[w.id],
                            onSelectedChange = { each[w.id] = it },
                            showAssignToMe = false,
                            labels = MonarchAssigneePickerLabels(label = "${w.count} ${w.label}", unassigned = {{handOver.unassigned}}),
                        )
                    }
                }
                MonarchButton(
                    text = {{cancel}},
                    onClick = { open = false },
                    modifier = Modifier.fillMaxWidth(),
                    variant = MonarchButtonVariant.Ghost,
                )
                MonarchButton(
                    text = {{continue}},
                    onClick = { step = 1 },
                    modifier = Modifier.fillMaxWidth(),
                    variant = MonarchButtonVariant.Primary,
                )
            } else {
                MonarchText(text = "Confirm removal", style = MonarchTextStyle.Heading)
                MonarchMemberRow(name = {{member.name}}, email = {{member.email}})
                MonarchConsequenceList(
                    items = listOf(MonarchConsequence(MonarchConsequenceKind.Removed, "{{member.name|raw}} loses access to the workspace")) +
                        work.map { w ->
                            val to = people.firstOrNull { it.id == assigneeOf(w.id) }?.name
                            if (to != null) {
                                MonarchConsequence(MonarchConsequenceKind.Changed, "${w.count} ${w.label} go to $to")
                            } else {
                                MonarchConsequence(MonarchConsequenceKind.Warning, "${w.count} ${w.label} are left unassigned")
                            }
                        } +
                        MonarchConsequence(MonarchConsequenceKind.Kept, "Their past activity and comments stay"),
                )
                failure?.let { MonarchInlineNotice(message = it, tone = MonarchTone.Danger) }
                MonarchButton(
                    text = "Remove member",
                    onClick = {
                        removing = true
                        failure = null
                        scope.launch {
                            // Send the removal and work.map { it.id to assigneeOf(it.id) } to the server here.
                            // On failure: failure = "Couldn’t remove {{member.name|raw}}. Try again."; removing = false
                            removing = false
                            sheet.dismiss()
                            val result = snackbars.showSnackbar(
                                message = "{{member.name|raw}} removed",
                                actionLabel = "Undo",
                                duration = SnackbarDuration.Long,
                            )
                            if (result == SnackbarResult.ActionPerformed) {
                                // Restore the membership and the work on the server.
                            }
                        }
                    },
                    modifier = Modifier.fillMaxWidth(),
                    variant = MonarchButtonVariant.Danger,
                    loading = removing,
                )
                MonarchButton(
                    text = "Back",
                    onClick = { step = 0 },
                    modifier = Modifier.fillMaxWidth(),
                    variant = MonarchButtonVariant.Ghost,
                    enabled = !removing,
                )
            }
        }
    }
}

